insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m136', 'k-research', 3, 'في إحدى الدراسات التربوية اختار الباحث نوعًا من العينات يُناسب المجتمعات التي يتوزع أفرادها على نطاق جغرافي واسع، ويُستخدم لتقليل الجهد والتكلفة، ويُطبَّق غالبًا عندما يكون المجتمع منظّمًا ضمن وحدات قائمة مثل المدارس أو الفصول أو الأحياء. ما نوع العينة التي تنطبق عليها هذه الخصائص؟', '["الحصصية","القصدية","الطبقية","العنقودية"]'::jsonb, 3, 'العينة العنقودية (متعددة المراحل) تختار وحدات كاملة قائمة (مدارس أو أحياء) على مراحل، وهي الأنسب للمجتمعات الكبيرة الواسعة الانتشار.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m137', 'k-research', 3, 'قام أحد الباحثين بإعداد استبانة لغرض بحث تربوي ومرّ بالإجراءات الآتية: (1) صياغة الاستبانة في صورتها النهائية، (2) عرض الصورة الأولية على عدد من المحكّمين، (3) تحديد الموضوع العام والمجالات الفرعية ثم كتابة الأسئلة، (4) تجريب الصورة الأولية على عينة محدودة من المجتمع. ما الترتيب الصحيح لهذه الإجراءات؟', '["3، 2، 4، 1","2، 3، 4، 1","3، 4، 2، 1","4، 3، 2، 1"]'::jsonb, 0, 'يبدأ الباحث بتحديد الموضوع والمجالات وكتابة الأسئلة (3)، ثم يعرضها على المحكّمين للتحقق من الصدق (2)، ثم يجربها على عينة محدودة للتحقق من الثبات (4)، ثم يخرجها في صورتها النهائية (1).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m138', 'k-research', 2, 'في إحدى الدراسات استخدم الباحث أداة مقابلة تضم قائمة موحدة من الأسئلة المحددة مسبقًا، والتزم بترتيبها وصياغتها نفسها لجميع المشاركين بهدف تسهيل تحليل الإجابات والمقارنة بينها. ما نوع المقابلة التي استخدمها الباحث؟', '["مقابلة بسيطة","مقابلة مقننة","مقابلة غير مقننة","مقابلة استكشافية"]'::jsonb, 1, 'المقابلة المقننة (المقيدة) تلتزم بأسئلة محددة مسبقًا بالترتيب والصياغة نفسها للجميع، فترتفع موضوعيتها وتسهل المقارنة بين الاستجابات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m139', 'k-research', 2, 'خلال زيارة صفية لاحظ مشرف تربوي تفاعل الطلاب مع أنشطة التعلّم التعاوني دون استخدام أداة منظمة مسبقًا، واكتفى بتسجيل انطباعاته العامة بعد نهاية الزيارة. ما نوع الملاحظة التي استخدمها المشرف في هذا السياق؟', '["ملاحظة مقننة","ملاحظة بسيطة","ملاحظة تشاركية","ملاحظة منظمة"]'::jsonb, 1, 'الملاحظة البسيطة تتم دون أداة مقننة ولا تحديد مسبق للسلوكيات، ويسجل الملاحظ انطباعاته العامة، فتقل موضوعيتها مقارنة بالمنظمة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m140', 'k-research', 3, 'يرغب باحث في جمع بيانات دقيقة عن مدى تمكن الطلاب من المهارات الكتابية في نهاية وحدة دراسية، ويشترط أن يكون أسلوب القياس موضوعيًا وقابلًا للتطبيق على عينة كبيرة، ويساعد في إصدار أحكام كمية حول مستوى الأداء. ما الأداة الأنسب لجمع البيانات في هذا البحث؟', '["الاستبانة","المقابلة","الملاحظة","الاختبار"]'::jsonb, 3, 'قياس مستوى التمكن من مهارة بأحكام كمية موضوعية على عينة كبيرة هو وظيفة الاختبار، أما الاستبانة فتقيس الآراء والاتجاهات لا مستوى الأداء.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m141', 'k-research', 2, 'سعى أحد المعلمين إلى التعرف على اتجاهات طلابه نحو استخدام التعلم الإلكتروني في مادته، وكان هدفه جمع بيانات من عدد كبير من الطلاب في وقت قصير بطريقة تضمن سهولة التحليل والمقارنة بين الأفراد. ما الأداة الأنسب لجمع البيانات في هذا السياق؟', '["الاستبانة","المقابلة","الملاحظة","الاختبار"]'::jsonb, 0, 'الاستبانة أنسب أدوات قياس الاتجاهات مع أعداد كبيرة في وقت قصير وبتكلفة منخفضة، وتسهّل التحليل الكمي والمقارنة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m142', 'k-research', 2, 'يرغب باحث في فهم العوامل النفسية والاجتماعية التي تؤثر على دافعية مجموعة من الطلاب منخفضي التحصيل، من خلال استكشاف مشاعرهم وتجاربهم وتفسيرهم الذاتي لصعوباتهم. أي من الأدوات التالية يتيح للباحث الوصول إلى هذه النوعية من البيانات؟', '["الاستبانة","المقابلة","الملاحظة","الاختبار"]'::jsonb, 1, 'المقابلة تتيح التعمق في المشاعر والدوافع والتفسيرات الذاتية عبر الحوار المباشر وإمكانية الاستيضاح، وهي أداة أساسية في البحث النوعي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m143', 'k-research', 3, 'هي الأداة التي تكون درجة الثقة في المعلومات التي يرصدها الباحث بواسطتها أكبر منها في بقية أدوات البحث، كما تتيح الحصول على بيانات أكثر تنوعًا:', '["الاستبانة","المقابلة","الملاحظة","الاختبار"]'::jsonb, 2, 'الملاحظة ترصد السلوك كما يقع فعلًا في بيئته الطبيعية دون الاعتماد على تقرير المبحوث عن نفسه، فترتفع الثقة في بياناتها وتتنوع.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m144', 'l-tarqeem', 1, 'علامة الترقيم التي توضع بين جملتين معطوفتين:', '["(.)","(،)","(- -)","(؛)"]'::jsonb, 1, 'الفاصلة توضع بين الجمل القصيرة المتصلة في المعنى والمعطوف بعضها على بعض.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m145', 'l-tarqeem', 3, '«إنَّ الحياة عندما تكون عملية يكون الحاضر فيها يخدم المستقبل ...... لذلك على المرء أن يتطلع فيها إلى الأمام ...... ولا يفكر فيما مضى ......» ما علامات الترقيم المناسبة للفراغات على الترتيب؟', '["(، / ، / .)","(، / ؛ / !)","(، / ، / !)","(؛ / ، / .)"]'::jsonb, 3, 'الفراغ الأول بين جملتين ثانيتهما نتيجة للأولى (بدليل «لذلك») فتوضع فاصلة منقوطة، والثاني بين جملتين معطوفتين فتوضع فاصلة، والثالث نهاية كلام تام فتوضع نقطة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m146', 'l-imla', 2, 'الكلمة المكتوبة بشكل صحيح فيما يأتي:', '["نمـى","سمى","عــدا","هــدا"]'::jsonb, 2, '«عدا» فعل ثلاثي ألفه أصلها واو (يعدو) فتكتب ألفًا قائمة. والصواب في البقية: نما وسما (واويان)، وهدى (يائي فتكتب مقصورة).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m147', 'l-imla', 2, '«طلب المعلم من الطالب .......... وانتظر ........» الكلمتان المناسبتان لملء الفراغين على الترتيب:', '["إجابة - استجابته","اجابة - إستجابته","إجابة - إستجابته","اجابة - استجابته"]'::jsonb, 0, '«إجابة» مصدر رباعي (أجاب) فهمزتها قطع، و«استجابة» مصدر سداسي (استجاب) فهمزتها وصل تكتب ألفًا دون همزة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m148', 'l-imla', 2, 'الكلمات الآتية همزتها همزة قطع ما عدا:', '["أكل","إجابة","أصاب","اركض"]'::jsonb, 3, '«اركض» فعل أمر من الثلاثي (ركض) وهمزته وصل. أما «أكل» ماضٍ ثلاثي مهموز، و«أصاب» رباعي، و«إجابة» مصدر رباعي فهمزاتها قطع.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m149', 'l-imla', 3, 'كُتبت الهمزة على واو في كلمة (تُؤَدة) لأنها:', '["مضمومة وما قبلها مضموم","مفتوحة وما قبلها مضموم","مضمومة وما قبلها مفتوح","مفتوحة وما قبلها مفتوح"]'::jsonb, 1, 'الهمزة متوسطة مفتوحة وما قبلها مضموم، والضمة أقوى من الفتحة فتكتب الهمزة على ما يناسب الأقوى وهو الواو.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m150', 'l-imla', 2, '«اهتموا بتربية ...............» الكلمة الصحيحة لملء الفراغ:', '["أبناءكم","أبناؤكم","أبنائكم","أبناأكم"]'::jsonb, 2, 'الكلمة مضاف إليه مجرور بالكسرة، والهمزة المتوسطة المكسورة تكتب على نبرة (ياء): أبنائِكم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m151', 'l-imla', 2, 'جاء في الحديث النبوي: «والحمد لله ......... الميزان». الكلمة الصحيحة لملء الفراغ:', '["تملء","تملئ","تمليء","تملأ"]'::jsonb, 3, 'الهمزة متطرفة وما قبلها حرف مفتوح (اللام)، والفتحة يناسبها الألف فتكتب: تملأ.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m152', 'l-imla', 3, '«لقد تحملت .............. كبيرًا». الكلمة الصحيحة لملء الفراغ:', '["عبءً","عبأً","عبئًا","عبءًا"]'::jsonb, 2, 'الكلمة مفعول به منصوب منوّن، والهمزة المتطرفة المسبوقة بساكن إذا نُوِّنت بالفتح كُتبت على نبرة واتصلت بها ألف التنوين: عبئًا.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m153', 'l-imla', 2, 'الأفعال الآتية صحيحة إملائيًا عدا:', '["ذهبوا","كتبوا","نرجوا","أقبلوا"]'::jsonb, 2, 'الألف الفارقة تُزاد بعد واو الجماعة في الأفعال فقط، و«نرجو» واوها أصلية من بنية الكلمة لا واو جماعة، فتكتب «نرجو» دون ألف.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m154', 'l-imla', 3, 'الجملة الصحيحة فيما يلي:', '["معلموا المدرسة نصحوا طلابهم","معلمو المدرسة نصحو طلابهم","معلموا المدرسة نصحو طلابهم","معلمو المدرسة نصحوا طلابهم"]'::jsonb, 3, '«معلمو» جمع مذكر سالم مضاف حُذفت نونه فلا تلحقه ألف فارقة، و«نصحوا» فعل اتصلت به واو الجماعة فتلحقه الألف الفارقة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m155', 'l-imla', 2, 'أي الكلمات الآتية ليس فيها حرف محذوف؟', '["تلك","هؤلاء","هذا","ذلك"]'::jsonb, 0, '«هذا» أصلها هاذا، و«ذلك» أصلها ذالك، و«هؤلاء» أصلها هاؤلاء، وحُذفت الألف من الثلاث نطقًا وكتابةً. أما «تلك» فلا حذف فيها.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m156', 'l-imla', 3, '«...... سيستمر الخلاف بينكم؟» البديل المناسب لملء الفراغ:', '["إلاما","إلامَ","إلامى","إلامأ"]'::jsonb, 1, 'إذا اتصلت «ما» الاستفهامية بحرف جر حُذفت ألفها: إلى + ما = إلامَ، ومثلها: علامَ، فيمَ، بمَ، لمَ.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m157', 'l-imla', 3, '«يا ربِّ إني ( ) فأجبني، و( ) فأسعدني». الكلمتان المناسبتان لوضعهما في الفراغين على الترتيب:', '["داعي، باكي","داعي، باكٍ","داعٍ، باكٍ","داعٍ، باكي"]'::jsonb, 2, 'كلٌّ من «داعٍ» و«باكٍ» اسم منقوص نكرة مرفوع، وتُحذف ياؤه ويُعوَّض عنها بتنوين العِوَض في حالتي الرفع والجر.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m158', 'l-imla', 2, 'أي ممَّا يأتي يمثل الرسم الإملائي الصحيح للجملة؟', '["حظر الضيف وقت الظهر","حضر الظيف وقت الضهر","حضر الضيف وقت الظهر","حضر الضيف وقت الضهر"]'::jsonb, 2, 'التمييز بين الضاد والظاء: حَضَر (بالضاد بمعنى أتى) وحَظَر (بالظاء بمعنى منع)، والضيف بالضاد، والظهر بالظاء.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m159', 'l-imla', 2, 'الكلمتان الصحيحتان إملائيًا فيما يأتي:', '["ضيف، ضمآن","ظيف، ظمآن","ضيف، ظمآن","ظيف، ضمآن"]'::jsonb, 2, '«ضيف» بالضاد، و«ظمآن» (العطشان) بالظاء. والخلط بين الضاد والظاء من أشهر الأخطاء الإملائية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m160', 'l-vocab', 2, 'معنى كلمة (الرَّوْع):', '["الغضب","الحزن","الفزع","البُعد"]'::jsonb, 2, 'الرَّوْع هو الفزع والخوف، ومنه قولهم: «هدأ رَوْعُه» أي سكن فزعه.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m161', 'l-vocab', 2, 'قال الشاعر: العينُ بعدَ فِراقها الوَطَنا *** لا ساكِنًا ألِفَت ولا سَكَنا. مرادف كلمة (أَلِفَتْ):', '["هجرت","عرفت","وجدت","أحبَّت"]'::jsonb, 3, 'أَلِفَ الشيءَ أي أنس به وأحبه واعتاده، وهو ضد النفور والهجر.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m162', 'l-writing', 2, 'من أنواع التعبير الإبداعي:', '["التقرير","الرسالة","المقــال","التلخيص"]'::jsonb, 2, 'التعبير الإبداعي يعبّر فيه الكاتب عن مشاعره وأفكاره بأسلوب أدبي كالمقال والخاطرة والقصة، أما التقرير والرسالة والتلخيص فمن التعبير الوظيفي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m163', 'l-writing', 2, 'من فنون الكتابة الوظيفية:', '["التلخيص","القصة","الخاطرة","المقالة"]'::jsonb, 0, 'الكتابة الوظيفية تقضي حاجة عملية في الحياة كالتلخيص والتقرير والرسائل الإدارية والسيرة الذاتية، بخلاف القصة والخاطرة والمقالة فهي إبداعية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m164', 'l-writing', 2, 'جميع ما يلي من مميزات الكتابة الوظيفية الموضوعية ما عدا:', '["تتضمن صورًا بلاغية","تتضمن بعض الأرقام","تتضمن حقائق وبراهين","تتضمن تقارير ومعلومات"]'::jsonb, 0, 'الكتابة الوظيفية تقوم على الوضوح والمباشرة والحقائق والأرقام، والصور البلاغية والخيال من سمات الكتابة الإبداعية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m165', 'l-writing', 2, 'يحق للكاتب إظهار رأيه الشخصي عند كتابة:', '["التلخيص","التقرير","المحضر","المقال"]'::jsonb, 3, 'المقال فن يعرض فيه الكاتب فكرته ورأيه ويدعمه بالحجج، أما التلخيص والتقرير والمحضر فتُلزم كاتبها الموضوعية والحياد.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m166', 'l-reading', 2, 'القراءة التي تقوم على تذكر التفاصيل والمعلومات الواردة في النص:', '["القراءة الآلية","القراءة الحرفية","القراءة التحليلية","القراءة الناقدة"]'::jsonb, 1, 'القراءة الحرفية أدنى مستويات الفهم، وتقتصر على استرجاع ما ورد في النص صراحةً دون تأويل أو حكم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m167', 'l-reading', 2, 'عندما يتفاعل القارئ مع المادة المقروءة فيحاورها ويعلن رأيه فيها سلبًا أو إيجابًا، فهذا يسمى بالقراءة:', '["الحرفية","التحليلية","الناقدة","الإبداعية"]'::jsonb, 2, 'القراءة الناقدة تتجاوز الفهم إلى إصدار الأحكام على النص وتقويم أفكاره وحججه.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m168', 'l-reading', 2, 'التنبؤ بنهاية الموضوع أو التوصل إلى توقعات للأحداث بناءً على فرضيات معينة من مهارات القراءة:', '["الحرفية","التحليلية","الناقدة","الإبداعية"]'::jsonb, 3, 'القراءة الإبداعية أعلى مستويات الفهم، ويتجاوز فيها القارئ النص إلى التوقع وتوليد الأفكار واقتراح البدائل والحلول.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m169', 'l-reading', 3, 'من استراتيجيات تسريع القراءة:', '["التلخيص","مشية الكنغر","طرح الأسئلة","القصــــة"]'::jsonb, 1, '«مشية الكنغر» من استراتيجيات القراءة السريعة، إذ تقفز العين بين الكلمات المفتاحية دون الوقوف على كل كلمة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m170', 'l-reading', 2, '«فصل الشتاء بالمملكة ممطر، فصل الشتاء أفضل وأمتع من فصل الصيف». العبارتان في الجملة السابقة تعبران عن:', '["حقيقة وحقيقة","رأي وحقيقة","رأي ورأي","حقيقة ورأي"]'::jsonb, 3, 'العبارة الأولى معلومة قابلة للتحقق فهي حقيقة، والثانية تفضيل شخصي يختلف باختلاف الناس (بدليل «أفضل وأمتع») فهي رأي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m171', 'l-imla', 3, '«حضرتُ ........... يغضب المعلم». الكلمة الصحيحة لملء الفراغ:', '["لأن لا","لألا","للأ","لئلا"]'::jsonb, 3, 'تتكون الكلمة من: لام التعليل + أنْ الناصبة + لا النافية، وتُدغم وتُكتب «لئلا» بهمزة على نبرة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m172', 'l-vocab', 2, 'مصدر الفعل (هذَّب):', '["إهذاب","مذهُّب","تهذيب","هذوب"]'::jsonb, 2, 'مصدر الفعل الرباعي على وزن «فعَّل» يأتي على وزن «تفعيل»: هذَّب ← تهذيب، ومثله: علَّم ← تعليم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m173', 'l-vocab', 2, 'جميع الكلمات الآتية مصادر ما عدا:', '["انتقل","ترتيب","تواصل","اكتتاب"]'::jsonb, 0, '«انتقل» فعل ماضٍ ومصدره «انتقال»، أما ترتيب وتواصل واكتتاب فمصادر.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m174', 'l-nahw', 3, '«زاد عدد المدارس من ........ مدارس إلى ......... مدرسة». العددان المناسبان لملء الفراغين:', '["خمس، اثنا عشر","خمسة، اثنتي عشرة","خمسة، اثنا عشر","خمس، اثنتي عشرة"]'::jsonb, 3, 'مفرد «مدارس» مؤنث (مدرسة) والعدد من 3 إلى 10 يخالف معدوده فيأتي «خمس» بلا تاء، والعدد 12 يوافق معدوده ويُعرب إعراب المثنى فيأتي بالياء بعد حرف الجر: اثنتي عشرة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m175', 'l-nahw', 3, '«بلغ عدد الطلاب (45) طالبًا». أي ممَّا يأتي هو الكتابة العربية الصحيحة للرقم السابق؟', '["خمسٌ وأربعون","خمسًا وأربعين","خمسةٌ وأربعون","خمسةً وأربعين"]'::jsonb, 2, 'المعدود «طالبًا» مذكر فيخالفه العدد المفرد بالتاء: خمسة. والعدد فاعل مرفوع فيُرفع المعطوف عليه كذلك: خمسةٌ وأربعون.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m176', 'l-imla', 2, 'الكلمة التي كُتبت تاؤها خطأ:', '["معلمات","فتيات","مقالات","مبالات"]'::jsonb, 3, 'الصواب «مبالاة» بتاء مربوطة لأنها مصدر مفرد وليست جمع مؤنث سالمًا، بخلاف معلمات وفتيات ومقالات فتاؤها مفتوحة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m177', 'l-nahw', 3, 'يقول الشاعر: سَعِدَتْ لِغُرَّةِ وَجْهِكَ الأيَّامُ *** وتَزَيَّنَتْ لِبَقائِكَ الأعْوَامُ. التاء في (سعدت) تعود على:', '["الأيام","الأعوام","الغرة","الوجه"]'::jsonb, 0, '«الأيامُ» فاعل مرفوع لفعل «سَعِدَتْ»، وتاء التأنيث الساكنة لحقت الفعل لأن فاعله جمع تكسير يعامل معاملة المؤنث.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m178', 'l-nahw', 3, '«إن .... بسرعة ........ ما أردت». الكلمتان المناسبتان لملء الفراغين السابقين:', '["تجر، تنال","تجري، تنل","تجري، تنال","تجر، تنل"]'::jsonb, 3, '«إن» أداة شرط جازمة تجزم فعلين: فعل الشرط «تجرِ» (مجزوم بحذف حرف العلة)، وجوابه «تنلْ» (مجزوم بالسكون).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('m179', 'l-nahw', 2, 'جميع الجمل الآتية صحيحة لغويًا ما عدا:', '["سافروا الرجال","الرجال سافروا","الرجال يسافرون","يسافر الرجال"]'::jsonb, 0, 'إذا تقدّم الفعل على فاعله الظاهر وجب إفراده فيقال «سافر الرجال»، وما في الخيار الأول يسمى لغة «أكلوني البراغيث» وهي لغة ضعيفة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
